WITH valid_stores AS (SELECT *, CONCAT(store_name, ' - ', region) store_name_region FROM stores WHERE LENGTH(store_name) < 8 AND region IS NULL), stores_stats AS (SELECT MONTH(opened_date) opened_month, MIN(opened_date) first_opened_date, COUNT(sqft) sqft_count FROM valid_stores GROUP BY MONTH(opened_date)) SELECT opened_month, sqft_count FROM stores_stats ORDER BY opened_month ASC, sqft_count DESC
